-- ==============================================================================
-- Migration: 20260930010000_fix_supabase_auth_rls.sql
-- Description: Decouple public.profiles from auth.users to support PRism's direct
--              GitHub OAuth identity system, while preserving all primary keys,
--              foreign key relationships, and RLS defense-in-depth.
-- ==============================================================================

-- 1. Remove foreign key constraint from profiles to auth.users
-- This allows deterministic PRism user UUIDs generated by the FastAPI backend
-- (derived from immutable GitHub IDs) to be persisted in public.profiles.
ALTER TABLE public.profiles
    DROP CONSTRAINT IF EXISTS profiles_id_fkey;

-- 2. Ensure RLS remains enabled on all tables as defense-in-depth
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.repositories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pull_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.review_findings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.engineering_memories ENABLE ROW LEVEL SECURITY;
